dashboard.definition:
{
	"title": "Detail Dashboard",
	"description": "P2 drill-down \u2014 detailed breakdowns for IT Health, User Experience, Security, and Building Resilience",
	"inputs": {
		"input_global_trp": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "global_time"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"options": {
				"fillColor": "#080e1a",
				"fillOpacity": 1,
				"strokeWidth": 0
			},
			"type": "splunk.rectangle"
		},
		"viz_title": {
			"options": {
				"fontColor": "#ffffff",
				"fontSize": "extraLarge",
				"markdown": "# Detail Dashboard \u2014 P2 Drill-Down"
			},
			"type": "splunk.markdown"
		},
		"viz_subtitle": {
			"options": {
				"fontColor": "#546e7a",
				"fontSize": "default",
				"markdown": "Detailed breakdowns across IT Health, User Experience, Security, and Building Resilience"
			},
			"type": "splunk.markdown"
		},
		"viz_it_section": {
			"options": {
				"fillColor": "#0877a6",
				"fillOpacity": 0.08,
				"rx": 10,
				"strokeColor": "#0877a6",
				"strokeOpacity": 0.3,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_it_header": {
			"options": {
				"fontColor": "#4fc3f7",
				"fontSize": "small",
				"markdown": "## IT / Critical Systems \u2014 Detail"
			},
			"type": "splunk.markdown"
		},
		"viz_it_q": {
			"options": {
				"fontColor": "#4fc3f7",
				"fontSize": "small",
				"markdown": "*Site breakdowns, issue analysis, device inventory by location*"
			},
			"type": "splunk.markdown"
		},
		"viz_top_sites_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Top 5 Sites by Issue Count**"
			},
			"type": "splunk.markdown"
		},
		"viz_top_sites_bar": {
			"dataSources": {
				"primary": "ds_top_sites_issues"
			},
			"options": {
				"backgroundColor": "transparent",
				"dataValuesDisplay": "all",
				"legendDisplay": "off",
				"seriesColors": [
					"#4fc3f7"
				],
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.bar"
		},
		"viz_issue_cat_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Network vs Client Issues**"
			},
			"type": "splunk.markdown"
		},
		"viz_issue_cat_donut": {
			"dataSources": {
				"primary": "ds_issue_category_split"
			},
			"options": {
				"backgroundColor": "transparent",
				"labelDisplay": "valuesAndPercentage",
				"seriesColors": [
					"#4fc3f7",
					"#81c784",
					"#546e7a"
				],
				"showDonutHole": true
			},
			"type": "splunk.pie"
		},
		"viz_wow_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Week-over-Week Health**"
			},
			"type": "splunk.markdown"
		},
		"viz_wow_value": {
			"dataSources": {
				"primary": "ds_wow_health"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 48,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"unit": "%"
			},
			"type": "splunk.singlevalue",
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 70,
						"value": "#d41f1f"
					},
					{
						"from": 70,
						"to": 85,
						"value": "#cba700"
					},
					{
						"from": 85,
						"value": "#118832"
					}
				]
			}
		},
		"viz_site_health_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Site-level Health**"
			},
			"type": "splunk.markdown"
		},
		"viz_site_health_table": {
			"context": {
				"rowBackgroundColorsByIndex": [
					"#0d1520",
					"#111b2b"
				]
			},
			"dataSources": {
				"primary": "ds_site_health"
			},
			"options": {
				"backgroundColor": "transparent",
				"count": 10,
				"headerVisibility": "fixed",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBackgroundColorsByIndex)"
				}
			},
			"type": "splunk.table"
		},
		"viz_top_net_issues_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Top 5 Network Issues**"
			},
			"type": "splunk.markdown"
		},
		"viz_top_net_issues_table": {
			"context": {
				"rowBackgroundColorsByIndex": [
					"#0d1520",
					"#111b2b"
				]
			},
			"dataSources": {
				"primary": "ds_top_network_issues"
			},
			"options": {
				"backgroundColor": "transparent",
				"count": 5,
				"headerVisibility": "fixed",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBackgroundColorsByIndex)"
				}
			},
			"type": "splunk.table"
		},
		"viz_top_client_issues_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Top 5 Client Issues**"
			},
			"type": "splunk.markdown"
		},
		"viz_top_client_issues_table": {
			"context": {
				"rowBackgroundColorsByIndex": [
					"#0d1520",
					"#111b2b"
				]
			},
			"dataSources": {
				"primary": "ds_top_client_issues"
			},
			"options": {
				"backgroundColor": "transparent",
				"count": 5,
				"headerVisibility": "fixed",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBackgroundColorsByIndex)"
				}
			},
			"type": "splunk.table"
		},
		"viz_wan_detail_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**WAN Bandwidth per Circuit**"
			},
			"type": "splunk.markdown"
		},
		"viz_wan_detail_table": {
			"context": {
				"rowBackgroundColorsByIndex": [
					"#0d1520",
					"#111b2b"
				]
			},
			"dataSources": {
				"primary": "ds_wan_bandwidth_detail"
			},
			"options": {
				"backgroundColor": "transparent",
				"count": 10,
				"headerVisibility": "fixed",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBackgroundColorsByIndex)"
				}
			},
			"type": "splunk.table"
		},
		"viz_ap_loc_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**AP Count by Location**"
			},
			"type": "splunk.markdown"
		},
		"viz_ap_loc_bar": {
			"dataSources": {
				"primary": "ds_ap_by_location"
			},
			"options": {
				"backgroundColor": "transparent",
				"dataValuesDisplay": "all",
				"legendDisplay": "off",
				"seriesColors": [
					"#4fc3f7"
				],
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.bar"
		},
		"viz_switch_loc_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Switch Count by Location**"
			},
			"type": "splunk.markdown"
		},
		"viz_switch_loc_bar": {
			"dataSources": {
				"primary": "ds_switch_by_location"
			},
			"options": {
				"backgroundColor": "transparent",
				"dataValuesDisplay": "all",
				"legendDisplay": "off",
				"seriesColors": [
					"#81c784"
				],
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.bar"
		},
		"viz_ux_section": {
			"options": {
				"fillColor": "#2e7d32",
				"fillOpacity": 0.08,
				"rx": 10,
				"strokeColor": "#2e7d32",
				"strokeOpacity": 0.3,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_ux_header": {
			"options": {
				"fontColor": "#81c784",
				"fontSize": "small",
				"markdown": "## User Experience \u2014 Detail"
			},
			"type": "splunk.markdown"
		},
		"viz_ux_q": {
			"options": {
				"fontColor": "#81c784",
				"fontSize": "small",
				"markdown": "*Client breakdowns, device types, OS distribution, WAN latency*"
			},
			"type": "splunk.markdown"
		},
		"viz_wireless_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Wireless Health**"
			},
			"type": "splunk.markdown"
		},
		"viz_wireless_gauge": {
			"dataSources": {
				"primary": "ds_wireless_health"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 48,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"unit": "%"
			},
			"type": "splunk.singlevalue",
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 70,
						"value": "#d41f1f"
					},
					{
						"from": 70,
						"to": 85,
						"value": "#cba700"
					},
					{
						"from": 85,
						"value": "#118832"
					}
				]
			}
		},
		"viz_wired_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Wired Health**"
			},
			"type": "splunk.markdown"
		},
		"viz_wired_gauge": {
			"dataSources": {
				"primary": "ds_wired_health"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 48,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"unit": "%"
			},
			"type": "splunk.singlevalue",
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 70,
						"value": "#d41f1f"
					},
					{
						"from": 70,
						"to": 85,
						"value": "#cba700"
					},
					{
						"from": 85,
						"value": "#118832"
					}
				]
			}
		},
		"viz_health_by_type_trend": {
			"dataSources": {
				"primary": "ds_client_health_by_type"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"seriesColors": [
					"#81c784",
					"#4fc3f7"
				],
				"xAxisLabelVisibility": "hide",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.area"
		},
		"viz_dev_types_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Top 5 Device Types**"
			},
			"type": "splunk.markdown"
		},
		"viz_dev_types_bar": {
			"dataSources": {
				"primary": "ds_top_device_types"
			},
			"options": {
				"backgroundColor": "transparent",
				"dataValuesDisplay": "all",
				"legendDisplay": "off",
				"seriesColors": [
					"#81c784"
				],
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.bar"
		},
		"viz_client_os_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Top 5 Client OS**"
			},
			"type": "splunk.markdown"
		},
		"viz_client_os_pie": {
			"dataSources": {
				"primary": "ds_top_client_os"
			},
			"options": {
				"backgroundColor": "transparent",
				"labelDisplay": "valuesAndPercentage",
				"seriesColors": [
					"#81c784",
					"#4fc3f7",
					"#ffb74d",
					"#ef9a9a",
					"#546e7a"
				],
				"showDonutHole": true
			},
			"type": "splunk.pie"
		},
		"viz_te_detail_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**ThousandEyes \u2014 Test Results**"
			},
			"type": "splunk.markdown"
		},
		"viz_te_detail_table": {
			"context": {
				"rowBackgroundColorsByIndex": [
					"#0d1520",
					"#111b2b"
				]
			},
			"dataSources": {
				"primary": "ds_te_tests"
			},
			"options": {
				"backgroundColor": "transparent",
				"count": 10,
				"headerVisibility": "fixed",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBackgroundColorsByIndex)"
				}
			},
			"type": "splunk.table"
		},
		"viz_te_trend_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**ThousandEyes \u2014 Latency Trend**"
			},
			"type": "splunk.markdown"
		},
		"viz_te_trend_line": {
			"dataSources": {
				"primary": "ds_te_latency_trend"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"seriesColors": [
					"#81c784"
				],
				"xAxisLabelVisibility": "hide",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.line"
		},
		"viz_wan_uplink_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**WAN Latency by Uplink**"
			},
			"type": "splunk.markdown"
		},
		"viz_wan_uplink_trend": {
			"dataSources": {
				"primary": "ds_wan_latency_by_uplink"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"seriesColors": [
					"#4fc3f7",
					"#81c784",
					"#ffb74d",
					"#ef9a9a",
					"#546e7a",
					"#ab47bc",
					"#26c6da",
					"#ff7043"
				],
				"xAxisLabelVisibility": "hide",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.line"
		},
		"viz_sec_section": {
			"options": {
				"fillColor": "#c62828",
				"fillOpacity": 0.08,
				"rx": 10,
				"strokeColor": "#c62828",
				"strokeOpacity": 0.3,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_sec_header": {
			"options": {
				"fontColor": "#ef9a9a",
				"fontSize": "small",
				"markdown": "## Security Resilience \u2014 Detail"
			},
			"type": "splunk.markdown"
		},
		"viz_sec_q": {
			"options": {
				"fontColor": "#ef9a9a",
				"fontSize": "small",
				"markdown": "*Identity analytics, DNS analysis, threat visibility*"
			},
			"type": "splunk.markdown"
		},
		"viz_priv_detail_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Top Privileged Users (AD 4672)**"
			},
			"type": "splunk.markdown"
		},
		"viz_priv_detail_table": {
			"context": {
				"rowBackgroundColorsByIndex": [
					"#1a0808",
					"#200c0c"
				]
			},
			"dataSources": {
				"primary": "ds_priv_detail"
			},
			"options": {
				"backgroundColor": "transparent",
				"count": 10,
				"headerVisibility": "fixed",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBackgroundColorsByIndex)"
				}
			},
			"type": "splunk.table"
		},
		"viz_priv_trend_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Privileged Logon Trend (14d)**"
			},
			"type": "splunk.markdown"
		},
		"viz_priv_trend_chart": {
			"dataSources": {
				"primary": "ds_priv_trend"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"seriesColors": [
					"#ef9a9a"
				],
				"xAxisLabelVisibility": "hide",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
