			},
			"type": "splunk.table"
		},
		"viz_identity_detail_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Identity Events Trend (AD + ISE, 14d)**"
			},
			"type": "splunk.markdown"
		},
		"viz_identity_detail_trend": {
			"dataSources": {
				"primary": "ds_identity_detail_trend"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"seriesColors": [
					"#81c784",
					"#ef5350",
					"#cba700",
					"#66bb6a",
					"#d41f1f"
				],
				"xAxisLabelVisibility": "hide",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.line"
		},
		"viz_dns_detail_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**DNS Blocked \u2014 Top Domains**"
			},
			"type": "splunk.markdown"
		},
		"viz_dns_detail_table": {
			"context": {
				"rowBackgroundColorsByIndex": [
					"#1a0808",
					"#200c0c"
				]
