	"dataSources": {
		"ds_site_map": {
			"name": "Site Locations",
			"type": "ds.search",
			"options": {
				"query": "| makeresults count=5 | streamstats count as id | eval name=case(id==1,\"Betty Easley Building\",id==2,\"Rudd Building\",id==3,\"Sadowski Building\",id==4,\"Breezeway\",id==5,\"SLRC\"), lat=case(id==1,30.4418,id==2,30.4385,id==3,30.4395,id==4,30.4400,id==5,28.5383), lon=case(id==1,-84.2809,id==2,-84.2815,id==3,-84.2820,id==4,-84.2812,id==5,-81.3792), location=case(id<=4,\"Tallahassee\",id==5,\"Orlando\"), role=case(id==1,\"Primary EOC \u00b7 33 Mbps\",id==2,\"Office\",id==3,\"Office\",id==4,\"Connector\",id==5,\"Secondary \u00b7 33 Mbps\") | fields - id | table lat lon name location role"
			}
		},
		"ds_link_graph": {
			"name": "Network Topology Flow",
			"type": "ds.search",
			"options": {
				"query": "| makeresults count=6 | streamstats count as id | eval Building=case(id==1,\"Betty Easley\",id==2,\"Rudd\",id==3,\"Sadowski\",id==4,\"Betty Easley\",id==5,\"Betty Easley\",id==6,\"SLRC\"), Connector=case(id<=3,\"Breezeway\",1==1,\"Direct\"), \"WAN Circuit\"=case(id<=3,\"EOC Internet (500M)\",id==4,\"Tally Public (100M)\",id==5,\"Betty Easley (33M)\",id==6,\"Orlando SLRC (33M)\") | fields Building Connector \"WAN Circuit\""
			}
		},
		"ds_bandwidth_ref": {
			"name": "WAN Circuit Bandwidth Reference",
			"type": "ds.search",
			"options": {
				"query": "| makeresults count=4 | streamstats count as id | eval Circuit=case(id==1,\"Tallahassee Public\",id==2,\"Tallahassee EOC Internet\",id==3,\"Betty Easley Public\",id==4,\"Orlando SLRC Public\"), Capacity=case(id==1,\"100 Mbps\",id==2,\"500 Mbps\",id==3,\"33 Mbps\",id==4,\"33 Mbps\"), \"Normal Avg\"=case(id==1,\"80 Mbps\",id==2,\"100 Mbps\",id==3,\"8 Mbps\",id==4,\"<4 Mbps\"), \"Activation Spike\"=case(id==1,\"120 Mbps\",id==2,\"~500 Mbps\",id==3,\"15 Mbps\",id==4,\"6 Mbps\") | fields - id | table Circuit Capacity \"Normal Avg\" \"Activation Spike\""
			}
		},
		"ds_sites_ref": {
			"name": "Site Reference",
			"type": "ds.search",
			"options": {
				"query": "| makeresults count=5 | streamstats count as id | eval Site=case(id==1,\"Betty Easley Building\",id==2,\"Rudd Building\",id==3,\"Sadowski Building\",id==4,\"Breezeway\",id==5,\"SLRC\"), Location=case(id<=4,\"Tallahassee\",id==5,\"Orlando\"), Role=case(id==1,\"Primary EOC, Public bandwidth 33 Mbps\",id==2,\"Office\",id==3,\"Office\",id==4,\"Connector\",id==5,\"Secondary, Public bandwidth 33 Mbps\") | fields - id | table Site Location Role"
			}
		},
		"ds_base_issues": {
			"name": "DNAC Issues (base)",
			"type": "ds.search",
			"options": {
				"query": "index=* sourcetype=\"cisco:dnac:issue\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			}
		},
		"ds_top_sites_issues": {
			"name": "Top 5 Sites by Issue Count",
			"type": "ds.chain",
			"options": {
				"extend": "ds_base_issues",
				"query": "| stats dc(IssueID) as count by SiteName | sort -count | head 5 | rename SiteName as site | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=5 | streamstats count as xi | eval site=case(xi==1,\"Betty Easley\",xi==2,\"Rudd Building\",xi==3,\"Sadowski\",xi==4,\"SLRC Orlando\",xi==5,\"Breezeway\"), count=case(xi==1,42,xi==2,28,xi==3,15,xi==4,11,xi==5,7) | table site count | fields - xi] | where isnull(xrc)] | fields - xrc"
			}
		},
		"ds_issue_category_split": {
			"name": "Network vs Client Issues",
			"type": "ds.chain",
			"options": {
				"extend": "ds_base_issues",
				"query": "| eval category=case(match(IssueCategory,\"(?i)network\"),\"Network\",match(IssueCategory,\"(?i)client\"),\"Client\",1==1,\"Other\") | stats dc(IssueID) as count by category | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=3 | streamstats count as xi | eval category=case(xi==1,\"Network\",xi==2,\"Client\",xi==3,\"Other\"), count=case(xi==1,38,xi==2,52,xi==3,13) | table category count | fields - xi] | where isnull(xrc)] | fields - xrc"
			}
		},
		"ds_top_network_issues": {
			"name": "Top 5 Network Issues",
			"type": "ds.chain",
			"options": {
				"extend": "ds_base_issues",
				"query": "| where match(IssueCategory,\"(?i)network\") | stats dc(IssueID) as Count by IssueName | sort -Count | head 5 | rename IssueName as Issue | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=5 | streamstats count as xi | eval Issue=case(xi==1,\"Switch port flapping\",xi==2,\"High interface utilization\",xi==3,\"OSPF neighbor down\",xi==4,\"AP disconnected\",xi==5,\"DHCP scope exhaustion\"), Count=case(xi==1,18,xi==2,12,xi==3,8,xi==4,6,xi==5,4) | table Issue Count | fields - xi] | where isnull(xrc)] | fields - xrc"
			}
		},
		"ds_top_client_issues": {
			"name": "Top 5 Client Issues",
			"type": "ds.chain",
			"options": {
				"extend": "ds_base_issues",
				"query": "| where match(IssueCategory,\"(?i)client\") | stats dc(IssueID) as Count by IssueName | sort -Count | head 5 | rename IssueName as Issue | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=5 | streamstats count as xi | eval Issue=case(xi==1,\"DHCP timeout\",xi==2,\"802.1x auth failure\",xi==3,\"DNS resolution failure\",xi==4,\"Poor RSSI\",xi==5,\"IP conflict\"), Count=case(xi==1,22,xi==2,15,xi==3,10,xi==4,8,xi==5,3) | table Issue Count | fields - xi] | where isnull(xrc)] | fields - xrc"
			}
		},
		"ds_base_nhealth": {
			"name": "DNAC Network Health (base)",
			"type": "ds.search",
			"options": {
				"query": "index=* sourcetype=\"cisco:dnac:networkhealth\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			}
		},
		"ds_site_health": {
			"name": "Site-level Health",
			"type": "ds.chain",
			"options": {
				"extend": "ds_base_nhealth",
				"query": "| where category!=\"All\" | stats latest(healthScore) as health by SiteName | sort -health | head 20 | rename SiteName as Site | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=5 | streamstats count as xi | eval Site=case(xi==1,\"Betty Easley\",xi==2,\"Rudd Building\",xi==3,\"Sadowski\",xi==4,\"SLRC Orlando\",xi==5,\"Breezeway\"), health=case(xi==1,92,xi==2,88,xi==3,85,xi==4,78,xi==5,95) | table Site health | fields - xi] | where isnull(xrc)] | fields - xrc"
			}
		},
		"ds_wow_health": {
			"name": "Week-over-Week Health Delta",
			"type": "ds.search",
			"options": {
				"query": "index=* sourcetype=\"cisco:dnac:networkhealth\" category=\"All\" | eval week=if(_time >= relative_time(now(), \"-7d@d\"), \"This_Week\", \"Last_Week\") | stats avg(healthScore) as score by week | xyseries _time week score | eval delta=round(This_Week - Last_Week, 1), score=round(This_Week) | append [| makeresults | eval score=85, delta=2.3] | head 1",
				"queryParameters": {
					"earliest": "-14d@d",
					"latest": "now"
				}
			}
		},
		"ds_base_dhealth": {
			"name": "DNAC Device Health (base)",
			"type": "ds.search",
			"options": {
				"query": "index=* sourcetype=\"cisco:dnac:devicehealth\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			}
		},
		"ds_ap_by_location": {
			"name": "AP Count by Location",
			"type": "ds.chain",
			"options": {
				"extend": "ds_base_dhealth",
