			"options": {
				"extend": "ds_base_chealth",
				"query": "| where clientType==\"WIRED\" AND scoreType==\"ALL\" | stats latest(scoreValue) as sv | eval score=if(sv>=0, sv*10, 0) | append [| makeresults | eval score=91] | head 1"
			}
		},
		"ds_client_health_by_type": {
