		"ds_wan_bandwidth_detail": {
			"name": "WAN Bandwidth per Circuit",
			"type": "ds.search",
			"options": {
				"query": "index=* sourcetype=\"meraki:devicesuplinkslossandlatency\" | stats latest(timeSeries{0}.latencyMs) as latency_ms, latest(timeSeries{0}.lossPercent) as loss_pct by uplink | eval latency_ms=round(latency_ms,1), loss_pct=round(loss_pct,2), status=case(latency_ms>100,\"Critical\", latency_ms>50,\"Warning\", 1==1,\"OK\") | rename uplink as circuit | head 20 | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=4 | streamstats count as xi | eval circuit=case(xi==1,\"Tally Public\",xi==2,\"Tally EOC\",xi==3,\"Betty Easley\",xi==4,\"Orlando SLRC\"), latency_ms=case(xi==1,18.2,xi==2,12.5,xi==3,22.1,xi==4,35.8), loss_pct=case(xi==1,0.1,xi==2,0.0,xi==3,0.3,xi==4,0.5), status=case(xi<=3,\"OK\",xi==4,\"Warning\") | table circuit latency_ms loss_pct status | fields - xi] | where isnull(xrc)] | fields - xrc",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			}
