		"ds_identity_detail_trend": {
			"name": "Identity Events Trend (AD + ISE)",
			"type": "ds.search",
			"options": {
				"query": "index=* ((sourcetype=\"XmlWinEventLog\" (EventCode=4624 OR EventCode=4625 OR EventCode=4740)) OR (sourcetype=\"cisco:ise:syslog\" (\"5200\" OR \"5400\"))) | eval evt=case(EventCode==4624,\"AD_Success\", EventCode==4625,\"AD_Failed\", EventCode==4740,\"AD_Lockout\", match(_raw,\"5200\"),\"ISE_Success\", match(_raw,\"5400\"),\"ISE_Failed\", 1==1,\"Other\") | where evt!=\"Other\" | timechart span=1d count by evt | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=14 | streamstats count as xi | eval _time=relative_time(now(), \"-\".xi.\"1d\"), AD_Success=round(random()%200+400), AD_Failed=round(random()%30+10), AD_Lockout=round(random()%3+1), ISE_Success=round(random()%100+150), ISE_Failed=round(random()%10+2) | fields - xi xrc] | where isnull(xrc)] | fields - xrc",
