				"query": "| stats count by domain | sort -count | head 10 | fillnull domain value=\"\u2014\" | rename domain as \"Blocked Domain\", count as Requests | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=5 | streamstats count as xi | eval \"Blocked Domain\"=case(xi==1,\"malware.evil.com\",xi==2,\"tracker.ads.net\",xi==3,\"phishing-site.ru\",xi==4,\"c2.badactor.io\",xi==5,\"cryptominer.xyz\"), Requests=case(xi==1,156,xi==2,89,xi==3,42,xi==4,28,xi==5,15) | table \"Blocked Domain\" Requests | fields - xi] | where isnull(xrc)] | fields - xrc"
