			"options": {
				"extend": "ds_base_dns",
				"query": "| timechart span=1d count as Blocked | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=14 | streamstats count as xi | eval _time=relative_time(now(), \"-\".xi.\"1d\"), Blocked=round(random()%50+20) | fields - xi xrc] | where isnull(xrc)] | fields - xrc"
			}
		},
		"ds_xdr_detail": {
			"name": "XDR Incident Details",
			"type": "ds.search",
			"options": {
				"query": "index=* (sourcetype=\"cisco:xdr:incident\" OR sourcetype=\"cisco:securex:incident\" OR sourcetype=\"cisco:cloud_security:incident\") | stats count by incident_id, severity, status, _time | sort -_time | head 10 | eval created=strftime(_time, \"%Y-%m-%d %H:%M\") | rename incident_id as incident | fields incident severity status created | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=5 | streamstats count as xi | eval incident=case(xi==1,\"INC-2026-0041\",xi==2,\"INC-2026-0039\",xi==3,\"INC-2026-0037\",xi==4,\"INC-2026-0035\",xi==5,\"INC-2026-0032\"), severity=case(xi==1,\"Critical\",xi==2,\"High\",xi==3,\"High\",xi==4,\"Medium\",xi==5,\"Low\"), status=case(xi==1,\"Investigating\",xi==2,\"Investigating\",xi==3,\"Contained\",xi==4,\"Resolved\",xi==5,\"Resolved\"), created=case(xi==1,strftime(relative_time(now(),\"-2h\"),\"%Y-%m-%d %H:%M\"),xi==2,strftime(relative_time(now(),\"-8h\"),\"%Y-%m-%d %H:%M\"),xi==3,strftime(relative_time(now(),\"-1d\"),\"%Y-%m-%d %H:%M\"),xi==4,strftime(relative_time(now(),\"-3d\"),\"%Y-%m-%d %H:%M\"),xi==5,strftime(relative_time(now(),\"-5d\"),\"%Y-%m-%d %H:%M\")) | fields incident severity status created] | where isnull(xrc)] | fields - xrc",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
