			"type": "ds.search",
			"options": {
				"query": "index=* sourcetype=\"meraki:sensorreadingshistory\" | timechart span=1h avg(temperature.fahrenheit) as Temperature, avg(humidity.relativePercentage) as Humidity | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=168 | streamstats count as xi | eval _time=relative_time(now(), \"-\".xi.\"1h\"), Temperature=round(random()%4+70,1), Humidity=round(random()%8+42,1) | fields - xi xrc] | where isnull(xrc)] | fields - xrc",
				"queryParameters": {
					"earliest": "-7d@d",
					"latest": "now"
				}
			}
		},
		"ds_ids_classification": {
			"name": "IDS/IPS Alerts by Classification",
			"type": "ds.search",
			"options": {
				"query": "index=* (sourcetype=\"cisco:sourcefire:defencecenter:syslog\" OR sourcetype=\"cisco:sourcefire:appliance:syslog\") | rex \"Classification: (?<classification>[^\\]]+)\" | rex \"Priority: (?<priority>\\d+)\" | stats count by classification, priority | sort -count | head 10 | rename classification as Classification, priority as Priority, count as Count | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=5 | streamstats count as xi | eval Classification=case(xi==1,\"A Network Trojan was Detected\",xi==2,\"Attempted Admin Privilege Gain\",xi==3,\"Potentially Bad Traffic\",xi==4,\"Not Suspicious Traffic\",xi==5,\"Attempted User Privilege Gain\"), Priority=case(xi<=2,1,xi==3,2,xi>=4,3), Count=case(xi==1,round(random()%10+5),xi==2,round(random()%8+3),xi==3,round(random()%15+8),xi==4,round(random()%20+10),xi==5,round(random()%5+2)) | fields Classification Priority Count] | where isnull(xrc)] | fields - xrc",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			}
		},
		"ds_email_security": {
			"name": "Email Security Details",
			"type": "ds.search",
			"options": {
				"query": "index=* (sourcetype=\"cisco:esa:amp\" OR sourcetype=\"cisco:esa:antispam\" OR sourcetype=\"cisco:esa:content_scanner\") | stats count by sourcetype | rename sourcetype as Source, count as Events | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=3 | streamstats count as xi | eval Source=case(xi==1,\"cisco:esa:amp\",xi==2,\"cisco:esa:antispam\",xi==3,\"cisco:esa:content_scanner\"), Events=case(xi==1,round(random()%50+20),xi==2,round(random()%100+50),xi==3,round(random()%80+30)) | fields Source Events] | where isnull(xrc)] | fields - xrc",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			}
		},
		"ds_web_security": {
			"name": "Web Security Details",
			"type": "ds.search",
			"options": {
				"query": "index=* (sourcetype=\"cisco:wsa:squid\" OR sourcetype=\"cisco:wsa:l4tm\") | stats count by sourcetype | rename sourcetype as Source, count as Events | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=2 | streamstats count as xi | eval Source=case(xi==1,\"cisco:wsa:squid\",xi==2,\"cisco:wsa:l4tm\"), Events=case(xi==1,round(random()%20+5),xi==2,round(random()%100+40)) | fields Source Events] | where isnull(xrc)] | fields - xrc",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			}
		},
		"ds_power_cooling_trend": {
			"name": "Power + Cooling Trend",
			"type": "ds.search",
			"options": {
				"query": "index=* sourcetype=\"Kepware\" | rex field=Tag \"(?<unit>PDU|CRAC)-\\d+\\.(?<metric>[\\w_]+)\" | eval kw=if(metric=\"W\", Value/1000, null()), temp=if(metric=\"Return_Air_Temperature\", Value, null()) | timechart span=30m sum(kw) as \"Total Power (kW)\", avg(temp) as \"Avg Return Air \u00b0F\" | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=48 | streamstats count as xi | eval _time=relative_time(now(), \"-\".xi.\"h\"), \"Total Power (kW)\"=round(random()%8+40, 1), \"Avg Return Air \u00b0F\"=round(random()%3+70, 1) | table _time \"Total Power (kW)\" \"Avg Return Air \u00b0F\"] | where isnull(xrc)] | fields - xrc",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			}
		},
		"ds_pdu_detail": {
			"name": "PDU Power Details",
			"type": "ds.search",
			"options": {
				"query": "index=* sourcetype=\"Kepware\" System=\"Power\" | rex field=Tag \"PDU-(?<PDU>\\d+)\\.(?<metric>\\w+)\" | stats latest(Value) as val by PDU, metric | eval Amps=if(metric=\"Amps\",val,null()), Volts=if(metric=\"Volts\",val,null()), Watts=if(metric=\"W\",val,null()) | stats first(Amps) as Amps, first(Volts) as Volts, first(Watts) as Watts by PDU | sort PDU | appendpipe [| stats count as xrc | where xrc==0 | append [| makeresults count=5 | streamstats count as xi | eval PDU=tostring(xi, \"0\"), Amps=round(random()%5+8,1), Volts=round(random()%3+208), Watts=round(random()%500+2000) | fields PDU Amps Volts Watts] | where isnull(xrc)] | fields - xrc",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			}
		}
	},
